// _agentbus — this file was generated by `agentbus install` and is removed by
// `agentbus uninstall`. Both of them look for this line: a file of this name
// without it is somebody's own and is never touched, so a copy you want to keep
// is a copy you rename.
//
// AGENTBUS_HOOK_VERSION=1
//
// The second of two files installed here, and the one the agent's terminal
// interface loads. It is named in that interface's own configuration rather
// than dropped into the plugin directory, because everything in that directory
// is loaded as an ordinary plugin and this is not one: what it exports is the
// interface's shape, and an ordinary plugin loader handed it would call it as
// something it is not.
//
// It forwards no events, because the interface produces none. What the
// interface has that the events do not is the session the user is looking at,
// known the moment they open it and not otherwise reported until something
// happens inside it — which on a session somebody opens and then reads is
// never. So this says which session that is, once, each time it changes.
//
// The interface offers nothing to subscribe to, so which session is open is
// read on a timer. The read is two property lookups and the report only goes
// when the answer is different, which is the difference between a poll costing
// nothing and a poll being noticed.
//
// The rules the other file is held to are the rules here: never throw, never
// wait, never speak. It runs inside somebody's session too.

import { spawn } from "node:child_process";

// Where this machine keeps the binary the reports are handed to. An absolute
// path, written in when the file was generated: the directory it lives in is
// not guaranteed to be on the `PATH` an agent runs its plugins with, and a
// command that cannot be found fails where nobody is looking.
const BINARY = "@BINARY@";

// What this file calls what it reports.
//
// Deliberately not one of the names the agent's own events go by. The other
// file forwards those verbatim, and a name shared with one of them would leave
// the mapping unable to tell a thing that happened from a thing that was
// noticed.
const EVENT = "tui.session.selected";

// How often the interface is asked which session it has open, in milliseconds.
// Short enough that nobody sees the gap between opening a session and it being
// reported, long enough that the answer is asked for a few times a second and
// not a few hundred.
const POLL_MS = 250;

// Hands one payload over and stops caring what becomes of it.
//
// The command and its arguments are passed separately rather than as a line for
// something else to split, so a path with a space or a quote in it reaches the
// binary as written. The child is released from the parent's accounting at
// once, which is what lets a session end without waiting for it, and both of
// the ways a spawn reports trouble asynchronously — a binary that is not there,
// a pipe closed before the payload was written — are listened for, because an
// unheard one of those is thrown at the session.
function handOver(payload) {
  try {
    const child = spawn(BINARY, ["emit", "--agent", "opencode"], {
      stdio: ["pipe", "ignore", "ignore"],
      windowsHide: true,
    });
    child.on("error", () => {});
    child.stdin.on("error", () => {});
    child.unref();
    child.stdin.end(JSON.stringify(payload));
  } catch {
    // Deliberately nothing. There is no failure here worth a user's attention.
  }
}

// Which session the interface has open, when that is a session in its own right.
//
// Nothing is reported for anything else it may be showing, and nothing for a
// session the agent started underneath another one: that one belongs to the
// work rather than to the person, and it ends by itself while the session they
// opened is still there.
function openSession(api) {
  try {
    const route = api?.route?.current;
    if (route?.name !== "session") {
      return undefined;
    }
    const id = route?.params?.sessionID;
    if (typeof id !== "string" || !id) {
      return undefined;
    }
    const session = api?.state?.session?.get(id);
    return !session || session.parentID ? undefined : id;
  } catch {
    return undefined;
  }
}

export default {
  id: "agentbus.opencode.session",
  tui: async (api) => {
    let reported;
    const look = () => {
      const open = openSession(api);
      if (!open || open === reported) {
        return;
      }
      reported = open;
      handOver({ type: EVENT, directory: process.cwd(), sessionID: open });
    };

    look();
    const timer = setInterval(look, POLL_MS);
    // A timer is a reason for a process to stay alive, and this one is not: it
    // is watching an interface that is on its way out by the time that matters.
    timer?.unref?.();
    api?.lifecycle?.onDispose?.(() => clearInterval(timer));
  },
};
